$$('[data-del-recipe]').forEach(b=>b.onclick=()=>{const used=db.meals.some(x=>String(x.recipeId)===String(b.dataset.delRecipe));if(used&&!confirm('Recipe old meal record mein use hui hai. Delete karne?'))return;db.recipes=db.recipes.filter(x=>String(x.id)!==String(b.dataset.delRecipe));save()});
form('mealForm',(f)=>{const ids=f.getAll('memberIds'),recipeId=f.get('recipeId'),recipe=db.recipes.find(x=>String(x.id)===String(recipeId));if(!ids.length){toast('Kam se kam ek member select karein');return}let cost=Number(f.get('cost')||0),used=[];if(recipe){cost=recipePerServing(recipe)*ids.length;const required=new Map();for(const ing of recipe.ingredients||[]){const item=db.stock.find(x=>String(x.id)===String(ing.stockId));if(!item){toast('Recipe ka ration store item missing hai');return}required.set(String(item.id),(required.get(String(item.id))||0)+ingredientBaseQty(ing)*ids.length)}for(const [stockId,needBase] of required){const item=db.stock.find(x=>String(x.id)===stockId),availableBase=stockBaseQty(item);if(needBase>availableBase+1e-8){toast(`${item.name} kam hai. Available ${Number(item.qty).toFixed(3)} ${item.unit}; recipe ke liye ${((needBase/unitFactor(normalizedUnit(item.unit))).toFixed(3))} ${item.unit} chahiye.`);return}used.push({stockId:item.id,name:item.name,quantityBase:needBase,unit:item.unit})}for(const u of used){const item=db.stock.find(x=>String(x.id)===String(u.stockId));item.qty=Math.max(0,Number(item.qty)-(u.quantityBase/unitFactor(normalizedUnit(item.unit))))}}db.meals.push({id:id(),date:f.get('date'),type:f.get('type'),recipeId:recipe?recipe.id:'',recipeName:recipe?.name||'',cost,memberIds:ids,note:f.get('note'),ingredientsUsed:used});save();toast(recipe?'Meal saved; ration stock automatic deduct hua':'Meal record saved')});
function updateMealEstimate(){const formEl=$('#mealForm');if(!formEl)return;const recipeId=formEl.querySelector('[name=recipeId]')?.value,recipe=db.recipes.find(x=>String(x.id)===String(recipeId)),count=$$('#mealForm input[name=memberIds]:checked').length;const costEl=formEl.querySelector('[name=cost]');if(!costEl)return;if(recipe){costEl.value=(recipePerServing(recipe)*count).toFixed(2);costEl.readOnly=true}else{costEl.readOnly=false}}
let recipeSel=$('#mealForm select[name=recipeId]');if(recipeSel)recipeSel.onchange=updateMealEstimate;$$('#mealForm input[name=memberIds]').forEach(c=>c.onchange=updateMealEstimate);updateMealEstimate();
if($('#mealTable'))$('#mealTable').onclick=e=>{const b=e.target.closest('[data-del-meal]');if(!b)return;const meal=db.meals.find(x=>String(x.id)===String(b.dataset.delMeal));if(!meal)return;if(!confirm('Meal record delete karein? Recipe ka ration stock wapas add ho jayega.'))return;for(const u of (meal.ingredientsUsed||[])){const item=db.stock.find(x=>String(x.id)===String(u.stockId));if(item){const base=Number(u.quantityBase)||0;item.qty=(Number(item.qty)||0)+(base/unitFactor(normalizedUnit(item.unit)))}}db.meals=db.meals.filter(x=>String(x.id)!==String(b.dataset.delMeal));save();toast('Meal delete hua; ration stock restore kar diya')};if($('#mealsMonth'))$('#mealsMonth').onchange=renderMealTable;
